<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$p=db();$d=$_SESSION['user']['department_id'];$semester=(int)($_GET['semester_id']??0);$semesters=$p->query('SELECT * FROM semesters ORDER BY semester_number')->fetchAll();$sql='SELECT s.*,se.semester_name FROM subjects s LEFT JOIN semesters se ON se.id=s.semester_id WHERE s.department_id=?';$args=[$d];if($semester){$sql.=' AND s.semester_id=?';$args[]=$semester;}$sql.=' ORDER BY se.semester_number,s.subject_code';$q=$p->prepare($sql);$q->execute($args);$title='Subjects';require __DIR__.'/../../includes/header.php';?><p><a class="button" href="add.php">Add Subject</a></p><section class="panel"><form method="get" class="inline-form"><label>Filter Semester<select name="semester_id"><option value="">All semesters</option><?php foreach($semesters as $sem):?><option value="<?=$sem['id']?>" <?=$semester===$sem['id']?'selected':''?>><?=e($sem['semester_name'])?></option><?php endforeach?></select></label><button>Filter</button></form></section><div class="panel table-wrap"><table><tr><th>Semester</th><th>Code</th><th>Name</th><th>Status</th><th></th></tr><?php foreach($q as $s):?><tr><td><?=e($s['semester_name']??'Not set')?></td><td><?=e($s['subject_code'])?></td><td><?=e($s['subject_name'])?></td><td><?=e($s['status'])?></td><td><a class="button secondary" href="edit.php?id=<?=$s['id']?>">Edit</a></td></tr><?php endforeach?></table></div><?php require __DIR__.'/../../includes/footer.php';?>
